from typing import List

class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        base = nums.count(k)
        best_gain = 0

        for target in range(1, 51):
            if target == k:
                continue

            cur = 0
            for num in nums:
                if num == target:
                    cur += 1
                elif num == k:
                    cur -= 1

                cur = max(cur, 0)
                best_gain = max(best_gain, cur)

        return base + best_gain
